class Solution {
  public Node flipBinaryTree(Node root, Node leaf) {
    Node cur = leaf, prev = null;
    while (cur != null) {
      Node oldParent = cur.parent;
      cur.parent = prev;
      if (oldParent == null) break;
      // detach cur from its old parent, then the old parent becomes cur's left child
      if (oldParent.left == cur) oldParent.left = null;
      else oldParent.right = null;
      if (cur.left != null) cur.right = cur.left;
      cur.left = oldParent;
      prev = cur;
      cur = oldParent;
    }
    return leaf;
  }
}
